  "record": {
   "title": "AIP-12 · Tell us what's slowing you down",
   "original_idea": "[AIP-12] Tell us what's slowing you down\nReel 9:16 · 20 s · Offer: business diagnostic · Bottom (decision) · 2026-12-11\n\nObjective:\nDirect-response close of the series. Aiphin asks the viewer three quick questions and invites them to send the answer on WhatsApp; a senior consultant replies within one business day.\n\nHook (EN):\nThree questions. Be honest.\n\nHook (AR):\nثلاثة أسئلة. أجب بصراحة.\n\nScene plan:\n0–2 s  Aiphin to camera, hook.\n2–14 s  Three questions pop in one by one: 'What do you answer by hand fifty times a week?' · 'Which report eats someone's whole day?' · 'Where do leads wait the longest?'\n14–18 s  'Send us your answer. A senior consultant replies within one business day.'\n18–20 s  End card with the WhatsApp number large.\nVisuals: Aiphin giving a thumbs up and winking (new pose), Aiphin thinking (reuse from AIP-02).\n\nCaption:\nThree questions:\n1. What do you answer by hand fifty times a week?\n2. Which report eats someone's whole day?\n3. Where do leads wait the longest?\n\nSend us your answers on WhatsApp. A senior consultant replies within one business day, usually with two or three questions before any quote.\n\nHashtags:\n#Aiphin #BusinessDiagnostic #Automation #MENA #Beirut\n\nCTA:\nMessage us on WhatsApp +961 71 313 917",
   "input_source": "csv",
   "source_reference": "research/out/aiphin_plan_01.json (Aiphin launch ideas, round 1) › Content › AIP-12",
   "content_type": "video",
   "language": "bilingual",
   "source_metadata": {
    "origin": "content_plan_import",
    "source_file": "research/out/aiphin_plan_01.json (Aiphin launch ideas, round 1)",
    "sheet": "Content",
    "plan_id": "AIP-12",
    "plan_status": "Idea, awaiting approval",
    "publish_date": "2026-12-11",
    "format": "Reel 9:16",
    "content_folder": null,
    "content_plan": {
     "ID": "AIP-12",
     "Status": "Idea, awaiting approval",
     "Publish date": "2026-12-11",
     "Format": "Reel 9:16",
     "Duration / slides": "20 s",
     "Title": "Tell us what's slowing you down",
     "Pillar": "Offer: business diagnostic",
     "Funnel": "Bottom (decision)",
     "Objective": "Direct-response close of the series. Aiphin asks the viewer three quick questions and invites them to send the answer on WhatsApp; a senior consultant replies within one business day.",
     "Hook EN (on screen, first 1.5 s)": "Three questions. Be honest.",
     "Hook AR": "ثلاثة أسئلة. أجب بصراحة.",
     "Scene plan (beat by beat)": "0–2 s  Aiphin to camera, hook.\n2–14 s  Three questions pop in one by one: 'What do you answer by hand fifty times a week?' · 'Which report eats someone's whole day?' · 'Where do leads wait the longest?'\n14–18 s  'Send us your answer. A senior consultant replies within one business day.'\n18–20 s  End card with the WhatsApp number large.\nVisuals: Aiphin giving a thumbs up and winking (new pose), Aiphin thinking (reuse from AIP-02).",
     "Caption": "Three questions:\n1. What do you answer by hand fifty times a week?\n2. Which report eats someone's whole day?\n3. Where do leads wait the longest?\n\nSend us your answers on WhatsApp. A senior consultant replies within one business day, usually with two or three questions before any quote.",
     "Hashtags": "#Aiphin #BusinessDiagnostic #Automation #MENA #Beirut",
     "CTA": "Message us on WhatsApp +961 71 313 917"
    }
   }
  }
 }
]$plan$::jsonb) loop
    res := public.create_project(
      v_ws, v_actor,
      (r -> 'record') || jsonb_build_object('brand_id', v_brand),
      r ->> 'dedupe_hash', false, r ->> 'source_key', false, v_batch);
    if (res ->> 'created')::boolean then
      v_created := v_created + 1;
      insert into public.tags (workspace_id, name)
      select v_ws, t from jsonb_array_elements_text(r -> 'tags') t
      on conflict (workspace_id, name) do nothing;
      insert into public.project_tags (project_id, tag_id)
      select (res ->> 'project_id')::uuid, tg.id from public.tags tg
      where tg.workspace_id = v_ws and tg.name in (select jsonb_array_elements_text(r -> 'tags'))
      on conflict do nothing;
    elsif (res ->> 'replayed')::boolean then
      v_existing := v_existing + 1;
    else
      v_duplicates := v_duplicates + 1;
    end if;
    v_report := v_report || jsonb_build_array(jsonb_build_object(
      'plan_id', r -> 'record' -> 'source_metadata' ->> 'plan_id',
      'project_id', res ->> 'project_id',
      'result', case when (res ->> 'created')::boolean then 'created'
                     when (res ->> 'replayed')::boolean then 'already_imported' else 'duplicate' end));
  end loop;

  -- Research evidence for posts that already exist: appended to their checks, never twice.
  for r in select value from jsonb_array_elements($evidence$[]$evidence$::jsonb) loop
    -- Content-sheet rows keep their checks in "Verify before approving (from the plan)", backlog rows in "Verify before approving".
    update public.content_projects p
    set source_metadata = jsonb_set(
          jsonb_set(p.source_metadata, '{content_plan}', coalesce(p.source_metadata -> 'content_plan', '{}'::jsonb)),
          array['content_plan', k.col],
          to_jsonb(concat_ws(E'

', nullif(p.source_metadata -> 'content_plan' ->> k.col, ''), r ->> 'note')))
        || jsonb_build_object('research_evidence', coalesce(p.source_metadata -> 'research_evidence', '[]'::jsonb) || jsonb_build_array(r ->> 'note'))
    from public.content_projects q
    cross join lateral (select case when q.source_metadata ->> 'sheet' = 'Content'
                                      or q.source_metadata -> 'content_plan' ? 'Verify before approving (from the plan)'
                                    then 'Verify before approving (from the plan)' else 'Verify before approving' end as col) k
    where q.id = p.id and p.workspace_id = v_ws and p.source_metadata ->> 'plan_id' = r ->> 'plan_id'
      and not coalesce(p.source_metadata -> 'research_evidence', '[]'::jsonb) ? (r ->> 'note')
    returning p.id into res_id;
    if res_id is not null then
      v_evidence := v_evidence + 1;
      perform public.log_event(res_id, 'plan.evidence_added', jsonb_build_object('note', r ->> 'note'), v_actor);
      res_id := null;
    elsif not exists (select 1 from public.content_projects where workspace_id = v_ws and source_metadata ->> 'plan_id' = r ->> 'plan_id') then
      raise notice 'Evidence for % skipped: no such post in this workspace', r ->> 'plan_id';
    end if;
  end loop;

  update public.import_batches
  set status = 'completed', created_count = v_created, duplicate_count = v_duplicates, report = v_report
  where id = v_batch;
  raise notice 'Content plan import: % created, % already imported, % duplicates of existing ideas, evidence added to % posts (batch %)',
    v_created, v_existing, v_duplicates, v_evidence, v_batch;
end
$import$;
